{
  "name": "OpenPLC 上传配置工具",
  "name_en": "OpenPLC Uploader Utility",
  "manufacturer": "",
  "description": "用于配置并上传 OpenPLC 相关参数的非实体图形工具，提供网络、端口、Modbus 与 I/O 选项的界面，实验中可用于准备控制逻辑部署和通信设置。",
  "description_en": "A non-physical graphical utility for configuring and uploading OpenPLC-related settings. It provides interfaces for network, port, Modbus, and I/O options, and is used in labs to prepare control-logic deployment and communication settings.",
  "actions": [
    {
      "action_name": "auto-hide_ioconfig",
      "description": "隐藏或显示 I/O 配置界面",
      "description_en": "Hide or show the I/O configuration interface."
    },
    {
      "action_name": "auto-init_ui",
      "description": "初始化图形界面",
      "description_en": "Initialize the graphical user interface."
    },
    {
      "action_name": "auto-load_config",
      "description": "加载配置",
      "description_en": "Load configuration."
    },
    {
      "action_name": "auto-on_close",
      "description": "处理窗口关闭操作",
      "description_en": "Handle the window close operation."
    },
    {
      "action_name": "auto-on_combo",
      "description": "处理下拉选项变化",
      "description_en": "Handle combo-box selection changes."
    },
    {
      "action_name": "auto-on_config_change",
      "description": "处理配置变更",
      "description_en": "Handle configuration changes."
    },
    {
      "action_name": "auto-on_port",
      "description": "处理端口选择或端口设置变化",
      "description_en": "Handle port selection or port setting changes."
    },
    {
      "action_name": "auto-on_result",
      "description": "处理上传或操作结果",
      "description_en": "Handle upload or operation results."
    },
    {
      "action_name": "auto-on_timer",
      "description": "处理定时器事件并检查编辑器结束状态",
      "description_en": "Handle timer events and check whether the editor has terminated."
    },
    {
      "action_name": "auto-on_update",
      "description": "处理更新或刷新操作",
      "description_en": "Handle update or refresh operations."
    },
    {
      "action_name": "auto-on_upload",
      "description": "启动上传操作",
      "description_en": "Start the upload operation."
    },
    {
      "action_name": "auto-save_config",
      "description": "保存配置",
      "description_en": "Save configuration."
    },
    {
      "action_name": "auto-get_config",
      "description": "获取配置",
      "description_en": "Get configuration."
    },
    {
      "action_name": "auto-on_wifi",
      "description": "处理 Wi‑Fi 设置变更",
      "description_en": "Handle Wi-Fi setting changes."
    },
    {
      "action_name": "auto-on_ip",
      "description": "处理 IP 地址设置变更",
      "description_en": "Handle IP address setting changes."
    },
    {
      "action_name": "auto-on_gw",
      "description": "处理网关设置变更",
      "description_en": "Handle gateway setting changes."
    },
    {
      "action_name": "auto-on_dns",
      "description": "处理 DNS 设置变更",
      "description_en": "Handle DNS setting changes."
    },
    {
      "action_name": "auto-on_subnet",
      "description": "处理子网掩码设置变更",
      "description_en": "Handle subnet mask setting changes."
    },
    {
      "action_name": "auto-on_mac",
      "description": "处理 MAC 地址设置变更",
      "description_en": "Handle MAC address setting changes."
    },
    {
      "action_name": "auto-enable_forms",
      "description": "启用或禁用表单输入区域",
      "description_en": "Enable or disable form input sections."
    },
    {
      "action_name": "auto-enable_tcp",
      "description": "启用或禁用 TCP 相关选项",
      "description_en": "Enable or disable TCP-related options."
    },
    {
      "action_name": "auto-update_src",
      "description": "更新源文件或来源路径显示",
      "description_en": "Update the source file or source path display."
    },
    {
      "action_name": "auto-get_values",
      "description": "获取界面当前输入值",
      "description_en": "Get the current values from the interface."
    },
    {
      "action_name": "auto-set_values",
      "description": "设置界面输入值",
      "description_en": "Set values in the interface."
    },
    {
      "action_name": "auto-on_id",
      "description": "处理设备 ID 或站号变化",
      "description_en": "Handle device ID or node address changes."
    },
    {
      "action_name": "auto-on_pins",
      "description": "处理引脚配置输入",
      "description_en": "Handle pin configuration input."
    },
    {
      "action_name": "auto-send_pin_change",
      "description": "发送引脚配置变更",
      "description_en": "Send pin configuration changes."
    },
    {
      "action_name": "auto-clear_master_en",
      "description": "清除主站相关启用状态",
      "description_en": "Clear master-related enabled states."
    },
    {
      "action_name": "auto-clear_slave_en",
      "description": "清除从站相关启用状态",
      "description_en": "Clear slave-related enabled states."
    },
    {
      "action_name": "auto-enable_slave",
      "description": "启用或禁用从站相关选项",
      "description_en": "Enable or disable slave-related options."
    },
    {
      "action_name": "auto-enable_master",
      "description": "启用或禁用主站相关选项",
      "description_en": "Enable or disable master-related options."
    },
    {
      "action_name": "auto-update_inputs",
      "description": "更新输入项显示或内容",
      "description_en": "Update input field display or contents."
    },
    {
      "action_name": "auto-enable_override",
      "description": "启用或禁用覆盖设置选项",
      "description_en": "Enable or disable override setting options."
    },
    {
      "action_name": "auto-on_inputs",
      "description": "处理输入配置变更",
      "description_en": "Handle input configuration changes."
    },
    {
      "action_name": "auto-on_io_change",
      "description": "处理 I/O 配置变化",
      "description_en": "Handle I/O configuration changes."
    },
    {
      "action_name": "auto-update_text_ctrl",
      "description": "更新文本输入控件内容",
      "description_en": "Update the text control contents."
    },
    {
      "action_name": "auto-exclude_en_pins",
      "description": "排除或禁用特定已启用引脚选项",
      "description_en": "Exclude or disable specific enabled pin options."
    },
    {
      "action_name": "auto-on_pin_change",
      "description": "处理单个引脚设置变化",
      "description_en": "Handle individual pin setting changes."
    }
  ],
  "tag_hints": [
    "OpenPLC",
    "PLC upload tool",
    "Modbus TCP/RTU configuration",
    "network settings",
    "I/O pin mapping",
    "wxPython GUI",
    "control logic deployment"
  ]
}

